    private RoomData data; private GameState state; private GameSession session; private Texture bg,onlineBg,exitBg; private BitmapFont f16,f24,f32; private final Map<String,TextureRegion> itemIcons=new HashMap<>(); private final HotspotEditor editor=new HotspotEditor(); private boolean editorEnabled,editorDragging; private float editorMouseX,editorMouseY; private int remoteWirePick=-1,remotePortPick=-1,remoteDevicePick=-1; private String[] targetWires={"White-Orange","Orange","White-Green","Blue","White-Blue","Green","White-Brown","Brown"},targetBoard={"Router","Switch","PC1","PC3"}; private int[][] targetLinks={{1,5},{2,3},{4,6},{7,8}}; private String targetDoorCode="2791";
    private String panel="",toast="",hover="",terminalInput="",terminalLine="",panelError="",panelObjectId="",chatInput=""; private TextureRegion panelCrop; private float toastTime,onlineFade,elapsed,chatToastTime; private boolean debug,networkDebug,disconnected,hostLeft,paused,hintOpen,exitMode,complete,lockdown,closed,failed,terminalCursor=true,handCursor,chatOpen,chatFocused,restrictedClue,partnerRoom3Ready,editingName; private final ChatModel chatModel=new ChatModel();private int chatScroll;
