    private void keypadClick(float x,float y){if(y<310&&x<720){exitMode=false;panel="";panelError="";return;}for(int i=0;i<12;i++){float bx=1000+(i%3)*165,by=465-(i/3)*100;if(x>=bx&&x<=bx+150&&y>=by&&y<=by+64){if(i==9)keypad="";else if(i==10&&keypad.length()<4)keypad+="0";else if(i<9&&keypad.length()<4)keypad+=(i+1);else if(i==11){if(targetDoorCode.equals(keypad)){play(successSound);showToast("Door unlocked");complete=true;exitMode=false;panel="";state.roomComplete=true;completeRoom();}else{play(errorSound);panelError="Wrong code";keypad="";}}if(beepSound!=null)play(beepSound);return;}}}
