    private void pauseClick(float x,float y){if(hostLeft){closeToMenu();return;}if(disconnected){if(y>455){if(session instanceof HostSession h){h.stop();session=new LocalSession(state,settings.playerName,null);}disconnected=false;paused=false;state.paused=false;state.pausedBy="";state.lockOwner.clear();saveState();}else if(y>340)showToast("Waiting for player to rejoin...");return;}if(y>560){paused=false;state.paused=false;state.pausedBy="";if(coop())session.submit(new Network.Intent(Network.Intent.Type.RESUME));session.publish();}else if(y>455){paused=false;state.paused=false;state.pausedBy="";if(coop())session.submit(new Network.Intent(Network.Intent.Type.RESUME));session.publish();open("pause_settings");}else{saveState();closeToMenu();}}
