    private void summaryClick(float x,float y){if(y<330)return;if(x<780){if(session instanceof RemoteSession){session.send(new Network.RoomReady());showToast("Waiting for host to start Room 3...");}else if(session instanceof HostSession host){if(!host.partnerConnected()||!partnerRoom3Ready){showToast("Waiting for "+host.partnerName()+"...");return;}host.beginRoom3();host.send(new Network.GameEvent("ROOM3_BEGIN",""));game.setScreen(new Room3Screen(game,session,false));}else{GameState next=new GameState();next.beginRoom3();LocalSession local=new LocalSession(next,settings.playerName,null);game.setScreen(new Room3Screen(game,local,false));}}else if(x<1200){if(coop()){if(session.isRemote())session.send(new Network.GameEvent("REPLAY",""));else restartCoop(true);}else restart();}else closeToMenu();}
    private void restart(){saveState();game.setScreen(new RoomScreen(game,false));}
    private void restartCoop(boolean announce){state.copyFrom(new GameState());complete=false;paused=false;lockdown=false;panel="";hintOpen=false;if(session instanceof HostSession h){h.setIntentOverride(this::applyRemoteIntent);h.publish();if(announce)h.send(new Network.GameEvent("REPLAY",""));}game.setScreen(new RoomScreen(game,session,false));}
