    private void useHint(){if(coop()){session.submit(new Network.Intent(Network.Intent.Type.USE_HINT));return;}String[] order={"P1","P2","P3","P4","P6","P7","P8"};for(String id:order)if(!isSolved(id)){hintPuzzle=id;int old=state.hintTiers.getOrDefault(id,0);selectedHintTier=Math.min(old+1,3);if(old<3){state.hintTiers.put(id,selectedHintTier);state.hintsUsed++;state.score=Math.max(0,state.score-50);state.secondsLeft=Math.max(0,state.secondsLeft-60);sessionRepo.record(sessionId,id,selectedHintTier);}hintText=hintFor(id,selectedHintTier);hintOpen=true;saveState();return;}showToast("No hints remaining.");}
    private String hintFor(String id,int tier){try{return hintManager.get(id,tier);}catch(Exception e){return "Hint data unavailable.";}}
    private boolean isSolved(String id){return switch(id){case "P1"->state.solved.contains("P3")||state.inventory.contains("Patch Cable")||state.inventory.containsAll(List.of("Crimping Tool","RJ45 Connectors","Cable Coil"));case "P2"->state.logbookRead;case "P3"->state.solved.contains("P3");case "P4"->state.routerOnline;case "P6"->state.boardSolved;case "P7"->state.pcSolved;case "P8"->complete;default->false;};}
    private void runCommand(){String c=terminalInput.trim();if(c.isEmpty())return;commandHistory.add(c);historyIndex=-1;terminalLines.add("> "+c);terminalInput="";if(session!=null&&session.isRemote()){Network.Intent i=new Network.Intent(Network.Intent.Type.TERMINAL_COMMAND);i.a=c;session.submit(i);return;}String[] p=c.split("\\s+",3);String cmd=p[0].toLowerCase(Locale.ROOT);String arg=p.length>1?p[1]:"";if(cmd.equals("help")){terminalLines.add("help, ipconfig, set ip <address>, set mask <mask>, set gateway <address>, ping <address>, mail, clear");}else if(cmd.equals("clear")){terminalLines.clear();}else if(cmd.equals("ipconfig")){terminalLines.add("IP: "+value(state.ip));terminalLines.add("MASK: "+value(state.mask));terminalLines.add("GATEWAY: "+value(state.gateway));}else if(cmd.equals("set")&&p.length==3){String target=arg.toLowerCase(Locale.ROOT);if(target.equals("ip"))state.ip=p[2];else if(target.equals("mask"))state.mask=p[2];else if(target.equals("gateway"))state.gateway=p[2];else{terminalLines.add("Unknown setting.");return;}terminalLines.add("OK");saveState();}else if(cmd.equals("ping")){ping(p.length>1?p[1]:"");}else if(cmd.equals("mail")){if(!state.pcSolved)terminalLines.add("No mail.");else{terminalLines.add("From: sysadmin");terminalLines.add("Subject: Door code");terminalLines.add("The exit door code has 4 digits.");terminalLines.add("Enter: the LEFT whiteboard digit, then 7, then the RIGHT whiteboard digit, then the router NODE ID.");}}else terminalLines.add("Unknown command. Type help.");}
    private String value(String s){return s.isEmpty()?"not set":s;}private void ping(String target){if(!state.routerOnline){terminalLines.add("Network adapter: no link.");return;}if(state.ip.isEmpty()||state.mask.isEmpty()||state.gateway.isEmpty()){terminalLines.add("Configure ip, mask and gateway first.");return;}if(!target.equals(state.gateway)){terminalLines.add("Request timed out.");return;}if(!state.ip.equals("192.168.1.30")){terminalLines.add("Destination unreachable. Check your IP address.");return;}if(!state.mask.equals("255.255.255.0")){terminalLines.add("Destination unreachable. Check your subnet mask.");return;}if(!state.gateway.equals("192.168.1.1")){terminalLines.add("Destination unreachable. Check your gateway.");return;}for(int i=0;i<4;i++)terminalLines.add("Reply from 192.168.1.1: bytes=32 time<1ms");terminalLines.add("Ping successful. You have mail.");state.pcSolved=true;state.solved.add("P7");play(successSound);showToast("Terminal ping successful");saveState();}
    private void forceCurrentPuzzleSolved(){if(!panel.isEmpty()){switch(panel){case "crimp"->{state.solved.add("P3");state.inventory.clear();state.inventory.add("Patch Cable");}case "patch"->{state.routerOnline=true;state.solved.add("P4");}case "topology"->{state.boardSolved=true;state.solved.add("P6");}case "terminal"->{state.pcSolved=true;state.solved.add("P7");}default->{}}saveState();}}
    private void reloadData(){try{data=RoomData.load();loadPuzzleData();hintManager.reload();showToast("Room and puzzle data reloaded");}catch(Exception e){showToast("Room data reload failed");}}
    private void showToast(String s){toast=s;toastTime=3;state.roomMessage=s;if(session instanceof HostSession h){String milestone=switch(s){case "Cable crimped"->"solved the cable crimp";case "Network link restored"->"restored the network";case "Hidden digits revealed"->"solved the whiteboard";case "Terminal ping successful"->"solved the terminal";default->"";};if(!milestone.isEmpty())h.systemLine(session.localName()+" "+milestone);}}
    private void play(Sound s){if(s!=null)s.play(Math.min(1f,settings.sfx*1.25f));}
    private void closeToMenu(){if(closed)return;closed=true;saveState();if(session!=null)session.close();game.setScreen(new LandingScreen(game));}
    private void completeRoom(){int time=2700-state.secondsLeft;state.roomComplete=true;complete=true;if(session!=null)session.publish();if(session==null||!session.isRemote())try{Path p=ProfilePaths.saves().resolve("progress.json");java.nio.file.Files.createDirectories(p.getParent());java.nio.file.Files.writeString(p,"{\"storySeen\":true,\"room\":3,\"room1\":{\"time\":"+time+",\"hints\":"+state.hintsUsed+",\"score\":"+state.score+"}}\n");}catch(Exception e){System.err.println("Could not save completion: "+e.getMessage());}if(coop()){if(game.getScreen() instanceof ExitScreen)game.setScreen(new RoomScreen(game,session,true));return;}game.setScreen(new RoomSummaryScreen(game,time,state.hintsUsed,state.score));}
    @Override public void resize(int w,int h){viewport.update(w,h,true);} @Override public void pause(){} @Override public void resume(){} @Override public void hide(){}
    @Override public void dispose(){batch.dispose();shapes.dispose();if(bg!=null)bg.dispose();if(onlineBg!=null)onlineBg.dispose();if(exitBg!=null)exitBg.dispose();if(f16!=null)f16.dispose();if(f24!=null)f24.dispose();if(f32!=null)f32.dispose();for(Sound s:new Sound[]{clickSound,pickupSound,successSound,errorSound,beepSound,roomHum,alarm})if(s!=null)s.dispose();sessionRepo.close();}
